const input = $input.first().json;
return [{ json: {
  query: `Fact-check this concept:
Headline: ${input.headline}
Body: ${input.concept_body}
Alignment: "${input.alignment_quote}" — ${input.alignment_why}

Source article: ${input.article_title}
URL: ${input.article_url}

${input.article_text}`,
  ...input
}}];

let raw = $input.first().json.output;
const prev = $('Build Context').first().json;

let parsed;
if (typeof raw === 'object' && raw !== null) {
  parsed = raw;
} else {
  let text = String(raw || '').trim();
  text = text.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?\s*```\s*$/, '').trim();
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    const match = text.match(/\{[\s\S]*"verdict"[\s\S]*\}$/);
    if (match) {
      try { parsed = JSON.parse(match[0]); } catch (e2) { parsed = null; }
    }
    if (!parsed) {
      parsed = { verdict: 'Unable to verify', body: text, writing_note: 'Treat source claims with caution.', sources_checked: [] };
    }
  }
}

return [{ json: { ...prev, ...parsed } }];

const d = $input.first().json;
const esc = v => String(v || '').replace(/'/g, "''");
return [{ json: {
  ...d,
  headline: esc(d.headline),
  concept_body: esc(d.concept_body),
  alignment_quote: esc(d.alignment_quote),
  alignment_priority: esc(d.alignment_priority),
  alignment_why: esc(d.alignment_why),
  verdict: esc(d.verdict),
  body: esc(d.body),
  writing_note: esc(d.writing_note),
  article_url: esc(d.article_url),
  article_hash: esc(d.article_hash),
  sources_checked_json: JSON.stringify(d.sources_checked || []).replace(/'/g, "''")
}}];

